es-e-030","sz-boundaries-e-031","sz-boundaries-e-032","sz-boundaries-e-033","sz-boundaries-e-035","e1018-t1-math_m1-11","e1018-t1-math_m1-15","e1018-t1-math_m2-25","e1018-t10-math_m2-44","e1018-t12-math_m2-64","e1018-t2-math_m1-20","e1018-t2-math_m2-23","e1018-t2-math_m2-26","e1018-t2-math_m2-39","e1018-t2-math_m2-56","e1018-t3-math_m1-4","e1018-t3-math_m1-6","e1018-t3-math_m1-10","e1018-t3-math_m2-27","e1018-t3-math_m2-30","e1018-t3-math_m2-56","e1018-t7-math_m2-56","e1018-t8-math_m2-55"]$satx$::jsonb; v_n int;
begin
  -- 1) draft sets: Test 14~26 drafts and Test 1~13 drafts newer than their published version (no attempts can reference a draft)
  delete from mock_exam_sets s where s.status = 'draft' and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and (s.name ~ '^SAT Practice Test (1[4-9]|2[0-6])$' or exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no and p.name ~ '^SAT Practice Test ([1-9]|1[0-3])$'));
  get diagnostics v_n = row_count; raise notice 'draft sets removed: %', v_n;
  -- 2) imported problems: unlink keywords, archive (not deleted) when no set uses them
  delete from problem_keywords where problem_id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' in (select jsonb_array_elements_text(v_gids)));
  update problems set archived_at = now() where id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' in (select jsonb_array_elements_text(v_gids)))
    and archived_at is null and not exists (select 1 from mock_exam_set_items i where i.problem_id = problems.id);
  get diagnostics v_n = row_count; raise notice 'imported problems archived: %', v_n;
end
$rb$;

do $audit$
declare
  v_rb constant jsonb := $audit_plan${"problems":[{"patch_id":"E1018-001","problem_id":"04964a5d-e2ab-43d9-92c5-f351665a2d8b","from_version_id":"f57bc084-ba17-46d4-8a76-835ddcb60181"},{"patch_id":"E1018-002","problem_id":"128d9ac6-8a0b-431d-9fce-f2e8fdc4025b","from_version_id":"e6f75a87-d578-4553-9511-9db9919ee8c3"},{"patch_id":"E1018-003","problem_id":"18b1bd7c-a481-4d8f-9126-11c9d812a384","from_version_id":"b8967aad-5c27-4317-b21b-60b10f8ba824"},{"patch_id":"E1018-004","problem_id":"1f290baa-6c3c-491e-b07d-e192b1b3d22d","from_version_id":"114e6b27-4625-4c01-b088-4be71271ebfe"},{"patch_id":"E1018-005","problem_id":"37cbca10-fbab-4c4c-b588-d135e95d4e3d","from_version_id":"d5eddd54-3ba7-46c3-8a7a-78e4b1f4f6a6"},{"patch_id":"E1018-006","problem_id":"40e262f6-9f45-4c0a-bd4d-be302cba48b9","from_version_id":"40e2cc55-d414-43b0-97b9-fe8b6bc62798"},{"patch_id":"E1018-007","problem_id":"7b871a5c-3aa1-405f-8627-811a1554124d","from_version_id":"b3251563-c13c-438c-96bd-77ff32715955"},{"patch_id":"E1018-008","problem_id":"7a5046de-096d-413b-97b1-4fe625d32a57","from_version_id":"beeb43d5-b1c6-4418-8a90-3507dab6dbbe"},{"patch_id":"E1018-009","problem_id":"886e6945-cb70-409a-bd67-7237f3e41c0f","from_version_id":"8f83b755-0771-483a-b207-fa74dd44e312"},{"patch_id":"E1018-010","problem_id":"4cd3e00b-6971-4183-a160-ccd27dffd3d9","from_version_id":"78c3ae7e-f14d-48b9-900e-3bfadb2c816d"},{"patch_id":"E1018-011","problem_id":"4e6f8402-e367-48c0-b483-ff764b7a00f4","from_version_id":"d209aeb2-2a04-47ea-a2af-115218726597"},{"patch_id":"E1018-012","problem_id":"988181a1-5e01-41c9-a186-1cd3666eabb3","from_version_id":"c908d45b-32e4-4831-a654-49dd8e416ebf"},{"patch_id":"E1018-013","problem_id":"c5e28308-63e7-409e-a0aa-fe1fc6b14cdf","from_version_id":"86bd79de-a3fc-4969-af2a-f6aeef35b203"},{"patch_id":"E1018-014","problem_id":"b157e20f-f903-4fae-ab71-ca8bc0484a40","from_version_id":"7eaea906-3e2e-42f8-a943-6095a1f29717"},{"patch_id":"E1018-015","problem_id":"37d6299b-501c-4a35-9a3f-99778f11d00c","from_version_id":"01e63647-198a-4718-92f8-511dbf820db9"},{"patch_id":"E1018-016","problem_id":"036c159a-86f9-427d-9287-d3ab5dc3e1f1","from_version_id":"9f64c324-40b4-4c68-810d-fd60fc7c87fe"},{"patch_id":"E1018-017","problem_id":"12848ace-6c3c-4a07-bd1d-0d7e864a36cd","from_version_id":"01cce6be-289c-487d-9e00-e6211f238124"},{"patch_id":"E1018-018","problem_id":"16d81cc7-54b9-4c1e-8855-481db79adebc","from_version_id":"f7978a81-f813-4481-9329-90370230bde4"},{"patch_id":"E1018-019","problem_id":"3c49d300-b7ae-4264-b8f3-941bbf941f42","from_version_id":"899387cf-3463-4048-a047-41fd53cc9139"},{"patch_id":"E1018-020","problem_id":"11b318f1-b7aa-4e9e-a1b1-e7a051376977","from_version_id":"1d49d80e-87e8-44a0-bdf4-6c21ee326d8d"},{"patch_id":"E1018-N001","problem_id":"2003abf7-832b-44e3-a770-1e1314595980","from_version_id":"2f3db046-1f7b-4cee-851d-1b43c2a241a0"},{"patch_id":"E1018-N002","problem_id":"d98b90e6-3528-4c9f-8202-43333a59aebb","from_version_id":"158b5c4c-7528-45a2-9a41-61d52c2ebd09"},{"patch_id":"E1018-N003","problem_id":"ca08743a-caac-40fa-bf32-44efd889efe5","from_version_id":"f8120efd-e731-4f33-9072-c3ebe8bb259f"},{"patch_id":"E1018-N004","problem_id":"4cc398c6-14b6-484c-82c3-5797d79d6ec5","from_version_id":"eb287df0-37a3-44dc-b3b7-2b22bcb64039"},{"patch_id":"E1018-N005","problem_id":"ec40556f-b296-40cc-9050-bb66d3eeca33","from_version_id":"69cb32ff-eac7-4538-b2a5-58ae131c0aed"}],"sets":[]}$audit_plan$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1);
  u jsonb; s jsonb; v_new uuid; v_old problem_versions%rowtype; v_n int := 0;
begin
  -- Problems first (the set publish gate needs each item's version to be the problem's current published version).
  for u in select * from jsonb_array_elements(v_rb->'problems') loop
    select id into v_new from problem_versions where problem_id = (u->>'problem_id')::uuid and status = 'published' and quality->'auditFix'->>'patch' = u->>'patch_id';
    if v_new is null then raise notice '[%] no audit version is published, skipped', u->>'patch_id'; continue; end if;
    select * into v_old from problem_versions where id = (u->>'from_version_id')::uuid;
    if v_old.id is null then raise exception '[%] previous version missing', u->>'patch_id'; end if;
    update problem_versions set status = 'archived' where id = v_new;
    update problem_versions set status = 'published' where id = v_old.id;
    update problems set passage = v_old.passage, options = v_old.options, correct_index = v_old.correct_index, explanation = v_old.explanation, published_version_id = v_old.id where id = v_old.problem_id;
    if u ? 'ap' then perform public.ap_attach_new_version(u->'ap'->>'candidate_key', (u->'ap'->>'item_index')::int, v_old.id, v_actor); end if;
    v_n := v_n + 1;
  end loop;
  -- Sets: archive the version created by the audit, republish the previous one (only when a newer version than the previous exists).
  for s in select * from jsonb_array_elements(v_rb->'sets') loop
    if exists (select 1 from mock_exam_sets n where n.set_group_id = (s->>'set_group_id')::uuid and n.status = 'published' and n.id <> (s->>'set_id')::uuid) then
      update mock_exam_sets set status = 'archived', archived_at = now() where set_group_id = (s->>'set_group_id')::uuid and status = 'published' and id <> (s->>'set_id')::uuid;
      update mock_exam_sets set status = 'published', archived_at = null, published_at = (s->>'published_at')::timestamptz, published_by = (s->>'published_by')::uuid, access_tier = coalesce(s->>'access_tier', access_tier)
       where id = (s->>'set_id')::uuid;
    end if;
  end loop;
  raise notice 'ROLLBACK DONE problems restored=%', v_n;
end
$audit$;

